import java.util.*;

class Solution {
    public int largestRectangleArea(int[] heights) {
        int n = heights.length;
        Deque<Integer> stack = new ArrayDeque<>();
        int maxArea = 0;

        for (int i = 0; i <= n; i++) {
            int currentHeight = (i == n) ? 0 : heights[i];
            while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
                int height = heights[stack.pop()];
                int width = stack.isEmpty() ? i : i - stack.peek() - 1;
                maxArea = Math.max(maxArea, height * width);
            }
            stack.push(i);
        }

        return maxArea;
    }
}

import java.util.*;

class Solution {
    public int largestRectangleArea(int[] heights) {
        int n = heights.length;
        int[] left = new int[n];
        int[] right = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();

        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
                stack.pop();
            }
            left[i] = stack.isEmpty() ? -1 : stack.peek();
            stack.push(i);
        }

        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
                stack.pop();
            }
            right[i] = stack.isEmpty() ? n : stack.peek();
            stack.push(i);
        }

        int maxArea = 0;
        for (int i = 0; i < n; i++) {
            int width = right[i] - left[i] - 1;
            maxArea = Math.max(maxArea, heights[i] * width);
        }

        return maxArea;
    }
}

import java.util.*;

class Solution {
    private int[] heights;
    private int[] tree;

    public int largestRectangleArea(int[] heights) {
        this.heights = heights;
        int n = heights.length;
        this.tree = new int[4 * n];
        build(1, 0, n - 1);

        int best = 0;
        Deque<int[]> ranges = new ArrayDeque<>();
        ranges.push(new int[] {0, n - 1});

        while (!ranges.isEmpty()) {
            int[] range = ranges.pop();
            int left = range[0];
            int right = range[1];
            if (left > right) {
                continue;
            }

            int minIndex = query(1, 0, n - 1, left, right);
            best = Math.max(best, heights[minIndex] * (right - left + 1));
            ranges.push(new int[] {left, minIndex - 1});
            ranges.push(new int[] {minIndex + 1, right});
        }

        return best;
    }

    private void build(int node, int left, int right) {
        if (left == right) {
            tree[node] = left;
            return;
        }
        int mid = left + (right - left) / 2;
        build(node * 2, left, mid);
        build(node * 2 + 1, mid + 1, right);
        tree[node] = better(tree[node * 2], tree[node * 2 + 1]);
    }

    private int query(int node, int left, int right, int queryLeft, int queryRight) {
        if (queryRight < left || right < queryLeft) {
            return -1;
        }
        if (queryLeft <= left && right <= queryRight) {
            return tree[node];
        }
        int mid = left + (right - left) / 2;
        int leftIndex = query(node * 2, left, mid, queryLeft, queryRight);
        int rightIndex = query(node * 2 + 1, mid + 1, right, queryLeft, queryRight);
        return better(leftIndex, rightIndex);
    }

    private int better(int first, int second) {
        if (first == -1) {
            return second;
        }
        if (second == -1) {
            return first;
        }
        return heights[first] <= heights[second] ? first : second;
    }
}

class Solution {
    public int largestRectangleArea(int[] heights) {
        int n = heights.length;
        int best = 0;

        for (int left = 0; left < n; left++) {
            int minHeight = Integer.MAX_VALUE;
            for (int right = left; right < n; right++) {
                minHeight = Math.min(minHeight, heights[right]);
                int width = right - left + 1;
                best = Math.max(best, minHeight * width);
            }
        }

        return best;
    }
}
